DROP TABLE IF EXISTS PERSON;

DROP SEQUENCE IF EXISTS PERSON_SEQ;

CREATE SEQUENCE PERSON_SEQ START WITH 1 INCREMENT BY 1;

-- ID BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
-- ID BIGINT DEFAULT NEXT VALUE FOR CUSTOMER_SEQ PRIMARY KEY,
-- id BIGINT GENERATED ALWAYS AS IDENTITY (START WITH 10 INCREMENT BY 1) PRIMARY KEY

CREATE TABLE PERSON
(
    ID          BIGINT          PRIMARY KEY,
    LASTNAME    VARCHAR(200)    NOT NULL,
    FIRSTNAME   VARCHAR(200)    NOT NULL,
    CREATED_AT  TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE PERSON IS 'Table for Persons';
COMMENT ON COLUMN PERSON.ID IS 'PrimaryKey';
COMMENT ON COLUMN PERSON.LASTNAME IS 'Lastname of Person';
COMMENT ON COLUMN PERSON.FIRSTNAME IS 'Firstname of Person';
COMMENT ON COLUMN PERSON.CREATED_AT IS 'Creation Timestamp of Person';
